package com.github.lingyan000.stevessr_generator_example

import android.app.Activity
import android.content.ClipData
import android.content.Intent
import androidx.core.content.FileProvider
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.File

/** Sends generated bytes to the Fluxdo activity that launched this plugin.
 * No credentials, cookies or raw filesystem paths are shared between APKs.
 */
class MainActivity : FlutterActivity() {
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(
            flutterEngine.dartExecutor.binaryMessenger,
            "com.github.lingyan000.fluxdo/generator_insert",
        ).setMethodCallHandler { call, result ->
            if (call.method != "insertGeneratedImage") {
                result.notImplemented()
                return@setMethodCallHandler
            }
            val bytes = call.argument<ByteArray>("bytes")
            val mime = call.argument<String>("mimeType")
            val extension = when (mime) {
                "image/png" -> "png"
                "image/jpeg" -> "jpg"
                "image/webp" -> "webp"
                "image/avif" -> "avif"
                else -> null
            }
            if (bytes == null || bytes.isEmpty() || bytes.size > 12 * 1024 * 1024 || extension == null) {
                result.error("INVALID_IMAGE", "Unsupported image or image exceeds 12 MiB", null)
                return@setMethodCallHandler
            }
            try {
                val directory = File(cacheDir, "generated").also { it.mkdirs() }
                val file = File(directory, "stevessr_${System.currentTimeMillis()}.$extension")
                file.writeBytes(bytes)
                val uri = FileProvider.getUriForFile(
                    this, "${applicationContext.packageName}.generated_images", file,
                )
                val payload = Intent().apply {
                    setDataAndType(uri, mime)
                    clipData = ClipData.newUri(contentResolver, "stevessr_image", uri)
                    addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                }
                setResult(Activity.RESULT_OK, payload)
                result.success(true)
                finish()
            } catch (error: Exception) {
                result.error("IMAGE_HANDOFF_FAILED", error.message, null)
            }
        }
    }
}
